{
    public class STA_StationService
    {
        private static DataTable dtbCache = null;
        private static bool bolHaveNewData = true;

        public static bool HaveNewData
        {
            get { return bolHaveNewData; }
            set { bolHaveNewData = value; }
        }

        public static DataTable GetAll()
        {
            if (bolHaveNewData || dtbCache == null)
